-- 555: Original BrillaPrep WASSCE Social Studies sprint 3 beta questions, part 2 of 15 (batch wassce-social-studies-sprint3-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_555_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_555_guard;
INSERT INTO _migration_555_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_005' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_gov' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The constitutional arrangement that allows each arm of government to limit the powers of the others so that no arm becomes too powerful is known as...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Checks and balances","B. Separation of powers","C. Rule of law","D. Judicial independence"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Separation of powers merely divides government functions among the three arms; checks and balances is the further mechanism by which each arm restrains the others — for example, presidential assent to bills and judicial review of executive action. (Rule of law means everyone is subject to the law; judicial independence protects judges from interference.) Therefore the correct answer is A: Checks and balances.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_005' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_555_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_006' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_gov' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which court in Ghana has the final authority to interpret the provisions of the 1992 Constitution?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The High Court","B. The Supreme Court","C. The Court of Appeal","D. The Regional Tribunal"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Article 130 of the 1992 Constitution gives the Supreme Court exclusive, original jurisdiction in the interpretation and enforcement of the Constitution, so its word is final. The High Court and Court of Appeal handle ordinary civil and criminal matters and appeals, and regional tribunals no longer exist under the current court structure. Therefore the correct answer is B: The Supreme Court.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_006' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_555_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_007' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_gov' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following is NOT a feature of a democratic system of government?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Free and fair periodic elections","B. Protection of fundamental human rights","C. Rule by a single political party without periodic elections","D. Equality of all citizens before the law"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Democracies hold periodic competitive elections, protect fundamental human rights and treat citizens equally before the law. Permanent one-party rule without elections removes the people’s power to change leaders, so it contradicts democracy. (The other three options are all standard features of democratic governance.) Therefore the correct answer is C: Rule by a single political party without periodic elections.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Select' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_007' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_555_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_008' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_gov' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Under the 1992 Constitution of Ghana, a person elected as President may serve a maximum of...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Three four-year terms","B. Two five-year terms","C. Unlimited terms of office","D. Two four-year terms"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Article 66 of the 1992 Constitution sets a presidential term at four years and bars anyone who has been elected twice from standing again — a maximum of two four-year terms. (Two five-year terms confuses Ghana with countries such as Nigeria’s neighbours with five-year terms; unlimited terms would remove a key check on executive power.) Therefore the correct answer is D: Two four-year terms.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_008' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_005', 'topic_wassce_p2_soc_gov', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'The constitutional arrangement that allows each arm of government to limit the powers of the others so that no arm becomes too powerful is known as...', 'multiple_choice', NULL, '["A. Checks and balances","B. Separation of powers","C. Rule of law","D. Judicial independence"]', 'A', 'Separation of powers merely divides government functions among the three arms; checks and balances is the further mechanism by which each arm restrains the others — for example, presidential assent to bills and judicial review of executive action. (Rule of law means everyone is subject to the law; judicial independence protects judges from interference.) Therefore the correct answer is A: Checks and balances.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_006', 'topic_wassce_p2_soc_gov', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'Which court in Ghana has the final authority to interpret the provisions of the 1992 Constitution?', 'multiple_choice', NULL, '["A. The High Court","B. The Supreme Court","C. The Court of Appeal","D. The Regional Tribunal"]', 'B', 'Article 130 of the 1992 Constitution gives the Supreme Court exclusive, original jurisdiction in the interpretation and enforcement of the Constitution, so its word is final. The High Court and Court of Appeal handle ordinary civil and criminal matters and appeals, and regional tribunals no longer exist under the current court structure. Therefore the correct answer is B: The Supreme Court.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_007', 'topic_wassce_p2_soc_gov', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'Which of the following is NOT a feature of a democratic system of government?', 'multiple_choice', NULL, '["A. Free and fair periodic elections","B. Protection of fundamental human rights","C. Rule by a single political party without periodic elections","D. Equality of all citizens before the law"]', 'C', 'Democracies hold periodic competitive elections, protect fundamental human rights and treat citizens equally before the law. Permanent one-party rule without elections removes the people’s power to change leaders, so it contradicts democracy. (The other three options are all standard features of democratic governance.) Therefore the correct answer is C: Rule by a single political party without periodic elections.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Select', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_008', 'topic_wassce_p2_soc_gov', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'Under the 1992 Constitution of Ghana, a person elected as President may serve a maximum of...', 'multiple_choice', NULL, '["A. Three four-year terms","B. Two five-year terms","C. Unlimited terms of office","D. Two four-year terms"]', 'D', 'Article 66 of the 1992 Constitution sets a presidential term at four years and bars anyone who has been elected twice from standing again — a maximum of two four-year terms. (Two five-year terms confuses Ghana with countries such as Nigeria’s neighbours with five-year terms; unlimited terms would remove a key check on executive power.) Therefore the correct answer is D: Two four-year terms.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'State', 'AO2', NULL, NULL, 'board_waec');
